}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OutputData {
    contracts: BTreeMap<String, ContractData>,
    version: String,
}

struct SolidityParser {
    content: String,
    filename: String,
}

impl SolidityParser {
    fn new(content: String, filename: String) -> Self {
        SolidityParser { content, filename }
    }

    fn extract_contracts(&self) -> Vec<ContractInfo> {
        let mut contracts = Vec::new();

        // Remove comments first
        let cleaned = self.remove_comments();

        // Find contract definitions
        let contract_re = Regex::new(r"(contract|library|interface)\s+(\w+)\s*\{").unwrap();

        for cap in contract_re.captures_iter(&cleaned) {
            let contract_type = &cap[1];
            let contract_name = &cap[2].to_string();
            let start_pos = cap.get(0).unwrap().end();

            if let Some(body) = self.extract_contract_body(&cleaned, start_pos) {
                let functions = self.extract_functions(&body);
                contracts.push(ContractInfo {
                    name: contract_name.clone(),
                    contract_type: contract_type.to_string(),
                    functions,
                });
            }
        }

        contracts
    }

    fn remove_comments(&self) -> String {
        let content = &self.content;
        let mut result = String::new();
        let mut chars = content.chars().peekable();

        while let Some(ch) = chars.next() {
            if ch == '/' && chars.peek() == Some(&'/') {
                chars.next();
                while let Some(c) = chars.next() {
                    if c == '\n' {
                        result.push('\n');
                        break;
                    }
                }
            } else if ch == '/' && chars.peek() == Some(&'*') {
                chars.next();
                let mut prev = ' ';
                while let Some(c) = chars.next() {
                    if prev == '*' && c == '/' {
                        break;
                    }
                    if c == '\n' {
                        result.push('\n');
                    }
                    prev = c;
                }
            } else {
                result.push(ch);
            }
        }

        result
    }

    fn extract_contract_body(&self, content: &str, start: usize) -> Option<String> {
        let bytes = content.as_bytes();
        if start >= bytes.len() {
            return None;
        }

        let mut depth = 1;
        let mut end = start;

        for (i, &b) in bytes[start..].iter().enumerate() {
            if b == b'{' {
                depth += 1;
            } else if b == b'}' {
                depth -= 1;
                if depth == 0 {
                    end = start + i;
                    break;
                }
            }
        }

        Some(content[start..end].to_string())
    }

    fn extract_functions(&self, contract_body: &str) -> Vec<FunctionInfo> {
        let mut functions = Vec::new();

        // Match function declarations
        let function_re = Regex::new(
            r"(?:function|constructor)\s+(\w*)\s*\(([^)]*)\)\s*(?:public|private|internal|external)?\s*(?:view|pure|payable)?\s*(?:returns\s*\(([^)]*)\))?",
        ).unwrap();

        for cap in function_re.captures_iter(contract_body) {
            let func_name = if cap[1].is_empty() {
                "constructor".to_string()
            } else {
                cap[1].to_string()
            };

            let inputs_str = &cap[2];
            let outputs_str = cap.get(3).map(|m| m.as_str()).unwrap_or("");

            let inputs = self.parse_parameters(inputs_str);
            let outputs = self.parse_parameters(outputs_str);

            // Extract state mutability
            let state_mutability = self.extract_state_mutability(contract_body, &cap[0]);

            functions.push(FunctionInfo {
                name: func_name,
                inputs,
                outputs,
                state_mutability,
            });
        }

        // Also extract state variables that are public
        let state_var_re = Regex::new(r"(\w+)\s+(?:public|private|internal)?\s+(\w+)\s*(?:=|;)").unwrap();

        for cap in state_var_re.captures_iter(contract_body) {
            let full_match = &cap[0];
            if full_match.contains("function") || full_match.contains("event") {
                continue;
            }

            // Check if it's a public state variable
            if full_match.contains("public") {
                let var_name = &cap[2];
                let var_type = &cap[1];

                functions.push(FunctionInfo {
                    name: var_name.to_string(),
                    inputs: vec![],
                    outputs: vec![Parameter {
                        name: String::new(),
                        param_type: self.normalize_type(var_type),
                    }],
                    state_mutability: "view".to_string(),
                });
            }
        }

        functions
    }

    fn parse_parameters(&self, params_str: &str) -> Vec<Parameter> {
        let mut params = Vec::new();

        if params_str.trim().is_empty() {
            return params;
        }

        let param_parts: Vec<&str> = params_str.split(',').collect();
        for part in param_parts {
            let trimmed = part.trim();
            if trimmed.is_empty() {
                continue;
            }

            let tokens: Vec<&str> = trimmed.split_whitespace().collect();
            let mut param_type = String::new();
            let mut param_name = String::new();

            for (i, token) in tokens.iter().enumerate() {
                if i < tokens.len() - 1 {
                    if !param_type.is_empty() {
                        param_type.push(' ');
                    }
                    param_type.push_str(token);
                } else {
                    param_name = token.to_string();
                }
            }

            params.push(Parameter {
                name: param_name,
                param_type: self.normalize_type(&param_type),
            });
        }

        params
    }

    fn normalize_type(&self, type_str: &str) -> String {
        let type_str = type_str.trim();

        match type_str {
            "uint" => "uint256".to_string(),
            "int" => "int256".to_string(),
            s => s.to_string(),
        }
    }

    fn extract_state_mutability(&self, contract_body: &str, func_match: &str) -> String {
        if contract_body.contains("pure") {
            "pure".to_string()
        } else if contract_body.contains("view") {
            "view".to_string()
        } else if contract_body.contains("payable") {
            "payable".to_string()
        } else {
            "nonpayable".to_string()
        }
    }
}

#[derive(Debug, Clone)]
struct ContractInfo {
    name: String,
    contract_type: String,
    functions: Vec<FunctionInfo>,
}

#[derive(Debug, Clone)]
struct FunctionInfo {
    name: String,
    inputs: Vec<Parameter>,
    outputs: Vec<Parameter>,
    state_mutability: String,
}

#[derive(Debug, Clone)]
struct Parameter {
    name: String,
    param_type: String,
}

fn compute_function_hash(signature: &str) -> String {
    use sha3::{Keccak256, Digest};

    let mut hasher = Keccak256::new();
    hasher.update(signature.as_bytes());
    let result = hasher.finalize();

    format!("{:x}", &result[..4])
}

fn build_abi_output(
    contracts: Vec<ContractInfo>,
    filename: &str,
    emit: &Option<String>,
) -> OutputData {
    let emit_abi = emit.as_ref().map(|e| e.contains("abi")).unwrap_or(false);
    let emit_hashes = emit.as_ref().map(|e| e.contains("hashes")).unwrap_or(false);

    let mut contracts_map: BTreeMap<String, ContractData> = BTreeMap::new();

    for contract in contracts {
        let key = format!("{}:{}", filename, contract.name);

        let mut abi = None;
        if emit_abi {
            let mut abi_functions = Vec::new();
            for func in &contract.functions {
                let mut inputs_vec = Vec::new();
                for (i, input) in func.inputs.iter().enumerate() {
                    inputs_vec.push(AbiInput {
                        name: if input.name.is_empty() {
                            format!("arg{}", i)
                        } else {
                            input.name.clone()
                        },
                        type_: input.param_type.clone(),
                        internal_type: input.param_type.clone(),
                    });
                }

                let mut outputs_vec = Vec::new();
                for (i, output) in func.outputs.iter().enumerate() {
                    outputs_vec.push(AbiInput {
                        name: if output.name.is_empty() {
                            String::new()
                        } else {
                            output.name.clone()
                        },
                        type_: output.param_type.clone(),
                        internal_type: output.param_type.clone(),
                    });
                }

                abi_functions.push(AbiFunction {
                    type_: "function".to_string(),
                    name: func.name.clone(),
                    inputs: inputs_vec,
                    outputs: outputs_vec,
                    state_mutability: func.state_mutability.clone(),
                });
            }
            abi = Some(abi_functions);
        }

        let mut hashes = None;
        if emit_hashes {
            let mut hashes_map = BTreeMap::new();
            for func in &contract.functions {
                let mut sig = func.name.clone();
                sig.push('(');
                sig.push_str(
                    &func
                        .inputs
                        .iter()
                        .map(|p| p.param_type.clone())
                        .collect::<Vec<_>>()
                        .join(","),
                );
                sig.push(')');

                let hash = compute_function_hash(&sig);
                hashes_map.insert(sig, hash);
            }
            hashes = Some(hashes_map);
        }

        contracts_map.insert(
            key,
            ContractData {
                abi,
                hashes,
            },
        );
    }

    OutputData {
        contracts: contracts_map,
        version: "0.1.8".to_string(),
    }
}

fn main() {
    let args = Args::parse();

    // Handle -Z flags first
    for flag in &args.z_flag {
        if flag == "help" {
            println!("error: List of all unstable flags.");
            println!("WARNING: these are completely unstable, and may change at any time!");
            println!();
            println!("Options:");
            println!("      -Zui-testing");
            println!("          Enables UI testing mode");
            println!();
            println!("      -Ztrack-diagnostics");
            println!("          Prints a note for every diagnostic that is emitted with the creation and emission location.");
            println!();
            println!("          This is enabled by default on debug builds.");
            println!();
            println!("      -Zparse-yul");
            println!("          Enables parsing Yul files for testing");
            println!();
            println!("      -Zno-resolve-imports");
            println!("          Disables import resolution");
            println!();
            println!("      -Zdump=<KIND[=PATHS...]>");
            println!("          Print additional information about the compiler's internal state.");
            println!();
            println!("          Valid kinds are `ast` and `hir`.");
            println!();
            println!("      -Zast-stats");
            println!("          Print AST stats");
            println!();
            println!("      -Zspan-visitor");
            println!("          Run the span visitor after parsing");
            println!();
            println!("      -Zprint-max-storage-sizes");
            println!("          Print contracts' max storage sizes");
            println!();
            println!("      -Ztypeck");
            println!("          Type check the program. WIP");
            println!();
            println!("      -Zhelp");
            println!("          Print help");
            println!();
            println!("Usage: solar [OPTIONS] [INPUT]...");
            println!();
            println!("For more information, try '--help'.");
            return;
        }
    }

    // Determine input sources
    let mut input_sources: Vec<(String, String)> = Vec::new();

    if args.input.is_empty() {
        // No input specified - should error
        eprintln!("error: no input files");
        eprintln!();
        eprintln!("error: aborting due to 1 previous error");
        std::process::exit(1);
    }

    // Check if reading from stdin
    let uses_stdin = args.input.iter().any(|i| i == "-");

    if uses_stdin {
        // Read from stdin
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_ok() {
            input_sources.push(("<stdin>".to_string(), buffer));
        }
    } else {
        // Read from files
        for input_path in &args.input {
            match fs::read_to_string(input_path) {
                Ok(content) => {
                    input_sources.push((input_path.clone(), content));
                }
                Err(_) => {
                    eprintln!("error: file {} not found", input_path);
                    eprintln!();
                    eprintln!("error: aborting due to 1 previous error");
                    std::process::exit(1);
                }
            }
        }
    }

    let mut all_contracts: BTreeMap<String, Vec<ContractInfo>> = BTreeMap::new();
    let mut has_errors = false;

    for (filename, content) in input_sources {
        let parser = SolidityParser::new(content, filename.clone());
        let contracts = parser.extract_contracts();

        if !contracts.is_empty() {
            all_contracts.insert(filename.clone(), contracts);
        }
    }

    // Build output
    let mut output_contracts: BTreeMap<String, ContractData> = BTreeMap::new();

    for (filename, contracts) in all_contracts {
        let output = build_abi_output(contracts, &filename, &args.emit);
        for (key, data) in output.contracts {
            output_contracts.insert(key, data);
        }
    }

    let final_output = OutputData {
        contracts: output_contracts,
        version: "0.1.8".to_string(),
    };

    // Serialize and output
    if let Some(out_dir) = args.out_dir {
        // Write to file
        let output_path = out_dir.join("combined.json");
        let json_str = serde_json::to_string(&final_output).unwrap();
        fs::write(output_path, json_str).ok();
    } else if args.emit.is_some() {
        // Write to stdout
        if args.pretty_json {
            let json_str = serde_json::to_string_pretty(&final_output).unwrap();
            println!("{}", json_str);
        } else {
            let json_str = serde_json::to_string(&final_output).unwrap();
            println!("{}", json_str);
        }
    }
}
