#[derive(Debug, Clone)]
struct Parameter {
    name: String,
    param_type: String,
}

fn compute_function_hash(signature: &str) -> String {
    use sha3::{Keccak256, Digest};

    let mut hasher = Keccak256::new();
    hasher.update(signature.as_bytes());
    let result = hasher.finalize();

    format!("{:x}", &result[..4])
}

fn build_abi_output(
    contracts: Vec<ContractInfo>,
    filename: &str,
    emit: &Option<String>,
) -> OutputData {
    let emit_abi = emit.as_ref().map(|e| e.contains("abi")).unwrap_or(false);
    let emit_hashes = emit.as_ref().map(|e| e.contains("hashes")).unwrap_or(false);

    let mut contracts_map: BTreeMap<String, ContractData> = BTreeMap::new();

    for contract in contracts {
        let key = format!("{}:{}", filename, contract.name);

        let mut abi = None;
        if emit_abi {
            let mut abi_functions = Vec::new();
            for func in &contract.functions {
                let mut inputs_vec = Vec::new();
                for (i, input) in func.inputs.iter().enumerate() {
                    inputs_vec.push(AbiInput {
                        name: if input.name.is_empty() {
                            format!("arg{}", i)
                        } else {
                            input.name.clone()
                        },
                        type_: input.param_type.clone(),
                        internal_type: input.param_type.clone(),
                    });
                }

                let mut outputs_vec = Vec::new();
                for (i, output) in func.outputs.iter().enumerate() {
                    outputs_vec.push(AbiInput {
                        name: if output.name.is_empty() {
                            String::new()
                        } else {
                            output.name.clone()
                        },
                        type_: output.param_type.clone(),
                        internal_type: output.param_type.clone(),
                    });
                }

                abi_functions.push(AbiFunction {
                    type_: "function".to_string(),
                    name: func.name.clone(),
                    inputs: inputs_vec,
                    outputs: outputs_vec,
                    state_mutability: func.state_mutability.clone(),
                });
            }
            abi = Some(abi_functions);
        }

        let mut hashes = None;
        if emit_hashes {
            let mut hashes_map = BTreeMap::new();
            for func in &contract.functions {
                let mut sig = func.name.clone();
                sig.push('(');
                sig.push_str(
                    &func
                        .inputs
                        .iter()
                        .map(|p| p.param_type.clone())
                        .collect::<Vec<_>>()
                        .join(","),
                );
                sig.push(')');

                let hash = compute_function_hash(&sig);
                hashes_map.insert(sig, hash);
            }
            hashes = Some(hashes_map);
        }

        contracts_map.insert(
            key,
            ContractData {
                abi,
                hashes,
            },
        );
    }

    OutputData {
        contracts: contracts_map,
        version: "0.1.8".to_string(),
    }
}

fn main() {
    let args = Args::parse();

    // Handle -Z flags first
    for flag in &args.z_flag {
        if flag == "help" {
            println!("error: List of all unstable flags.");
            println!("WARNING: these are completely unstable, and may change at any time!");
            println!();
            println!("Options:");
            println!("      -Zui-testing");
            println!("          Enables UI testing mode");
            println!();
            println!("      -Ztrack-diagnostics");
            println!("          Prints a note for every diagnostic that is emitted with the creation and emission location.");
            println!();
            println!("          This is enabled by default on debug builds.");
            println!();
            println!("      -Zparse-yul");
            println!("          Enables parsing Yul files for testing");
            println!();
            println!("      -Zno-resolve-imports");
            println!("          Disables import resolution");
            println!();
            println!("      -Zdump=<KIND[=PATHS...]>");
            println!("          Print additional information about the compiler's internal state.");
            println!();
            println!("          Valid kinds are `ast` and `hir`.");
            println!();
            println!("      -Zast-stats");
            println!("          Print AST stats");
            println!();
            println!("      -Zspan-visitor");
            println!("          Run the span visitor after parsing");
            println!();
            println!("      -Zprint-max-storage-sizes");
            println!("          Print contracts' max storage sizes");
            println!();
            println!("      -Ztypeck");
            println!("          Type check the program. WIP");
            println!();
            println!("      -Zhelp");
            println!("          Print help");
            println!();
            println!("Usage: solar [OPTIONS] [INPUT]...");
            println!();
            println!("For more information, try '--help'.");
            return;
        }
    }

    // Determine input sources
    let mut input_sources: Vec<(String, String)> = Vec::new();

    if args.input.is_empty() {
        // No input specified - should error
        eprintln!("error: no input files");
        eprintln!();
        eprintln!("error: aborting due to 1 previous error");
        std::process::exit(1);
    }

    // Check if reading from stdin
    let uses_stdin = args.input.iter().any(|i| i == "-");

    if uses_stdin {
        // Read from stdin
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_ok() {
            input_sources.push(("<stdin>".to_string(), buffer));
        }
    } else {
        // Read from files
        for input_path in &args.input {
            match fs::read_to_string(input_path) {
                Ok(content) => {
                    input_sources.push((input_path.clone(), content));
                }
                Err(_) => {
                    eprintln!("error: file {} not found", input_path);
                    eprintln!();
                    eprintln!("error: aborting due to 1 previous error");
                    std::process::exit(1);
                }
            }
        }
    }

    let mut all_contracts: BTreeMap<String, Vec<ContractInfo>> = BTreeMap::new();
    let mut has_errors = false;

    for (filename, content) in input_sources {
        let parser = SolidityParser::new(content, filename.clone());
        let contracts = parser.extract_contracts();

        if !contracts.is_empty() {
            all_contracts.insert(filename.clone(), contracts);
        }
    }

    // Build output
    let mut output_contracts: BTreeMap<String, ContractData> = BTreeMap::new();

    for (filename, contracts) in all_contracts {
        let output = build_abi_output(contracts, &filename, &args.emit);
        for (key, data) in output.contracts {
            output_contracts.insert(key, data);
        }
    }

    let final_output = OutputData {
        contracts: output_contracts,
        version: "0.1.8".to_string(),
    };

    // Serialize and output
    if let Some(out_dir) = args.out_dir {
        // Write to file
        let output_path = out_dir.join("combined.json");
        let json_str = serde_json::to_string(&final_output).unwrap();
        fs::write(output_path, json_str).ok();
    } else if args.emit.is_some() {
        // Write to stdout
        if args.pretty_json {
            let json_str = serde_json::to_string_pretty(&final_output).unwrap();
            println!("{}", json_str);
        } else {
            let json_str = serde_json::to_string(&final_output).unwrap();
            println!("{}", json_str);
        }
    }
}
