struct AbiFunction {
    #[serde(rename = "type")]
    type_: String,
    name: String,
    inputs: Vec<AbiInput>,
    outputs: Vec<AbiInput>,
    #[serde(rename = "stateMutability")]
    state_mutability: String,
}

#[derive(Debug, Clone)]
struct AbiInput {
    name: String,
    #[serde(rename = "type")]
    type_: String,
    #[serde(rename = "internalType")]
    internal_type: String,
}

#[derive(Debug, Clone)]
struct OutputData {
    contracts: BTreeMap<String, ContractData>,
    version: String,
}

fn build_abi(contract: &ContractInfo) -> Vec<AbiFunction> {
    let mut abi = Vec::new();

    for func in &contract.functions {
