                    result.push_str("\",\n");
                    result.push_str("              \"type\": \"");
                    result.push_str(&input.type_);
                    result.push_str("\",\n");
                    result.push_str("              \"internalType\": \"");
                    result.push_str(&input.internal_type);
                    result.push_str("\"\n");
                    result.push_str("            }");
                }

                result.push_str("\n          ],\n");
                result.push_str("          \"outputs\": [\n");

                for (j, output) in func.outputs.iter().enumerate() {
                    if j > 0 {
                        result.push_str(",\n");
                    }
                    result.push_str("            {\n");
                    result.push_str("              \"name\": \"");
                    result.push_str(&output.name);
                    result.push_str("\",\n");
                    result.push_str("              \"type\": \"");
                    result.push_str(&output.type_);
                    result.push_str("\",\n");
                    result.push_str("              \"internalType\": \"");
                    result.push_str(&output.internal_type);
                    result.push_str("\"\n");
                    result.push_str("            }");
                }

                result.push_str("\n          ],\n");
                result.push_str("          \"stateMutability\": \"");
                result.push_str(&func.state_mutability);
                result.push_str("\"\n");
                result.push_str("        }");
            }
            result.push_str("\n      ]\n");
            first_field = false;
        }

        if let Some(hashes) = &contract_data.hashes {
            if !first_field {
                result.push_str(",\n");
            }
            result.push_str("      \"hashes\": {\n");

            let mut first_hash = true;
            for (sig, hash) in hashes {
                if !first_hash {
                    result.push_str(",\n");
                }
                first_hash = false;

                result.push_str("        \"");
                result.push_str(sig);
                result.push_str("\": \"");
                result.push_str(hash);
                result.push_str("\"");
            }

            result.push_str("\n      }\n");
        }

        result.push_str("    }");
    }

    result.push_str("\n  },\n");
    result.push_str("  \"version\": \"");
    result.push_str(&data.version);
    result.push_str("\"\n}\n");

    result
}

