fn keccak_sponge(input: &[u8]) -> [u8; 32] {
    // Keccak-256 parameters
    const RATE: usize = 136; // r = 1088 bits = 136 bytes for Keccak256
    const CAPACITY: usize = 256 / 8; // c = 256 bits = 32 bytes
    const OUTPUT_LEN: usize = 32;

    let mut state = [0u64; 25];

    // Padding
    let mut padded = Vec::from(input);
    padded.push(0x06); // Domain separation for SHA-3
    while (padded.len() % RATE) != (RATE - 1) {
        padded.push(0x00);
    }
    padded.push(0x80); // End padding

    // Absorb phase
    for chunk in padded.chunks(RATE) {
        for (i, byte_chunk) in chunk.chunks(8).enumerate() {
            let mut val = 0u64;
            for (j, &b) in byte_chunk.iter().enumerate() {
                val |= (b as u64) << (8 * j);
            }
            state[i] ^= val;
        }
        keccak_f(&mut state);
    }

    // Squeeze phase
    let mut output = [0u8; 32];
    let mut out_pos = 0;
    while out_pos < OUTPUT_LEN {
        for i in 0..((RATE / 8).min((OUTPUT_LEN - out_pos) / 8)) {
            let bytes = state[i].to_le_bytes();
            let copy_len = (8).min(OUTPUT_LEN - out_pos);
            output[out_pos..out_pos + copy_len].copy_from_slice(&bytes[..copy_len]);
            out_pos += copy_len;
        }
        if out_pos < OUTPUT_LEN {
            keccak_f(&mut state);
        }
    }

    output
}

fn keccak_f(state: &mut [u64; 25]) {
    const ROUNDS: usize = 24;

    for round in 0..ROUNDS {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }

        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }

        for x in 0..5 {
            for y in 0..5 {
                state[x + 5 * y] ^= d[x];
            }
        }

        // Rho and Pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5 * y;
                b[y + 5 * ((2 * x + 3 * y) % 5)] = state[idx].rotate_left(RHO_OFFSETS[idx]);
            }
        }

        // Chi
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5 * y;
                state[idx] = b[idx] ^ ((!b[(x + 1) % 5 + 5 * y]) & b[(x + 2) % 5 + 5 * y]);
            }
        }

        // Iota
        state[0] ^= ROUND_CONSTANTS[round];
    }
}

const RHO_OFFSETS: [u32; 25] = [
    0, 1, 62, 28, 27,
    36, 44, 6, 55, 20,
    3, 10, 43, 25, 39,
    41, 45, 15, 21, 8,
    18, 2, 61, 56, 14,
];

const ROUND_CONSTANTS: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a,
    0x8000000080008000, 0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008a,
    0x0000000000000088, 0x0000000080000001, 0x000000008000008b,
    0x000000008000008a, 0x0000000000008089, 0x0000000000008003,
    0x0000000000008002, 0x0000000000000080, 0x000000000000800a,
    0x800000008000000a, 0x8000000080008081, 0x8000000000008080,
    0x0000000080000001, 0x8000000080008008, 0x0000000000000000,
];

