mod hex {
    pub fn decode(s: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
        let mut result = Vec::new();
        for i in (0..s.len()).step_by(2) {
            if i + 1 < s.len() {
                let byte = u8::from_str_radix(&s[i..i+2], 16)?;
                result.push(byte);
            }
        }
        Ok(result)
    }
}

