fn build_abi(contract: &ContractInfo) -> Vec<AbiFunction> {
    let mut abi = Vec::new();

    for func in &contract.functions {
        let mut inputs = Vec::new();
        for (i, param) in func.inputs.iter().enumerate() {
            inputs.push(AbiInput {
                name: if param.name.is_empty() {
                    format!("arg{}", i)
                } else {
                    param.name.clone()
                },
                type_: param.param_type.clone(),
                internal_type: param.param_type.clone(),
            });
        }

        let mut outputs = Vec::new();
        for param in func.outputs.iter() {
            outputs.push(AbiInput {
                name: param.name.clone(),
                type_: param.param_type.clone(),
                internal_type: param.param_type.clone(),
            });
        }

        abi.push(AbiFunction {
            type_: "function".to_string(),
            name: func.name.clone(),
            inputs,
            outputs,
            state_mutability: func.state_mutability.clone(),
        });
    }

    abi
}

fn build_hashes(contract: &ContractInfo) -> BTreeMap<String, String> {
    let mut hashes = BTreeMap::new();

    for func in &contract.functions {
        let mut sig = func.name.clone();
        sig.push('(');
        sig.push_str(
            &func
                .inputs
                .iter()
                .map(|p| p.param_type.clone())
                .collect::<Vec<_>>()
                .join(","),
        );
        sig.push(')');

        let hash = compute_function_hash(&sig);
        hashes.insert(sig, hash);
    }

    hashes
}

fn compute_function_hash(signature: &str) -> String {
    let hash = keccak256(signature.as_bytes());
    format!("{:02x}{:02x}{:02x}{:02x}", hash[0], hash[1], hash[2], hash[3])
}

fn keccak256(input: &[u8]) -> [u8; 32] {
    keccak_sponge(input)
}

// Implement Keccak-256 sponge construction
fn keccak_sponge(input: &[u8]) -> [u8; 32] {
    // Keccak-256 parameters
    const RATE: usize = 136; // r = 1088 bits = 136 bytes for Keccak256
    const OUTPUT_LEN: usize = 32;

    let mut state = [0u64; 25];

    // Padding
    let mut padded = Vec::from(input);
    padded.push(0x06); // Domain separation for SHA-3
    while (padded.len() % RATE) != (RATE - 1) {
        padded.push(0x00);
    }
    padded.push(0x80); // End padding

    // Absorb phase
    for chunk in padded.chunks(RATE) {
        for (i, byte_chunk) in chunk.chunks(8).enumerate() {
            let mut val = 0u64;
            for (j, &b) in byte_chunk.iter().enumerate() {
                val |= (b as u64) << (8 * j);
            }
            state[i] ^= val;
        }
        keccak_f(&mut state);
    }

    // Squeeze phase
    let mut output = [0u8; 32];
    let mut out_pos = 0;
    while out_pos < OUTPUT_LEN {
        for i in 0..((RATE / 8).min((OUTPUT_LEN - out_pos) / 8)) {
            let bytes = state[i].to_le_bytes();
            let copy_len = (8).min(OUTPUT_LEN - out_pos);
            output[out_pos..out_pos + copy_len].copy_from_slice(&bytes[..copy_len]);
            out_pos += copy_len;
        }
        if out_pos < OUTPUT_LEN {
            keccak_f(&mut state);
        }
    }

    output
}

fn keccak_f(state: &mut [u64; 25]) {
    const ROUNDS: usize = 24;

    for round in 0..ROUNDS {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }

        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }

        for x in 0..5 {
            for y in 0..5 {
                state[x + 5 * y] ^= d[x];
            }
        }

        // Rho and Pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5 * y;
                b[y + 5 * ((2 * x + 3 * y) % 5)] = state[idx].rotate_left(RHO_OFFSETS[idx]);
            }
        }

        // Chi
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5 * y;
                state[idx] = b[idx] ^ ((!b[(x + 1) % 5 + 5 * y]) & b[(x + 2) % 5 + 5 * y]);
            }
        }

        // Iota
        state[0] ^= ROUND_CONSTANTS[round];
    }
}

const RHO_OFFSETS: [u32; 25] = [
    0, 1, 62, 28, 27,
    36, 44, 6, 55, 20,
    3, 10, 43, 25, 39,
    41, 45, 15, 21, 8,
    18, 2, 61, 56, 14,
];

const ROUND_CONSTANTS: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a,
    0x8000000080008000, 0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008a,
    0x0000000000000088, 0x0000000080000001, 0x000000008000008b,
    0x000000008000008a, 0x0000000000008089, 0x0000000000008003,
    0x0000000000008002, 0x0000000000000080, 0x000000000000800a,
    0x800000008000000a, 0x8000000080008081, 0x8000000000008080,
    0x0000000080000001, 0x8000000080008008, 0x0000000000000000,
];

fn serialize_json(data: &OutputData, pretty: bool) -> String {
    if pretty {
        format_json_pretty(data)
    } else {
        format_json_compact(data)
    }
}

fn format_json_compact(data: &OutputData) -> String {
    let mut result = String::from("{\"contracts\":{");

    let mut first_contract = true;
    for (key, contract_data) in &data.contracts {
        if !first_contract {
            result.push(',');
        }
        first_contract = false;

        result.push('"');
        result.push_str(key);
        result.push_str("\":{");

        let mut first_field = true;

        if let Some(abi) = &contract_data.abi {
            result.push_str("\"abi\":[");
            for (i, func) in abi.iter().enumerate() {
                if i > 0 {
                    result.push(',');
                }
                result.push_str("{\"type\":\"function\",\"name\":\"");
                result.push_str(&func.name);
                result.push_str("\",\"inputs\":[");

                for (j, input) in func.inputs.iter().enumerate() {
                    if j > 0 {
                        result.push(',');
                    }
                    result.push_str("{\"name\":\"");
                    result.push_str(&input.name);
                    result.push_str("\",\"type\":\"");
                    result.push_str(&input.type_);
                    result.push_str("\",\"internalType\":\"");
                    result.push_str(&input.internal_type);
                    result.push_str("\"}");
                }

                result.push_str("],\"outputs\":[");

                for (j, output) in func.outputs.iter().enumerate() {
                    if j > 0 {
                        result.push(',');
                    }
                    result.push_str("{\"name\":\"");
                    result.push_str(&output.name);
                    result.push_str("\",\"type\":\"");
                    result.push_str(&output.type_);
                    result.push_str("\",\"internalType\":\"");
                    result.push_str(&output.internal_type);
                    result.push_str("\"}");
                }

                result.push_str("],\"stateMutability\":\"");
                result.push_str(&func.state_mutability);
                result.push_str("\"}");
            }
            result.push(']');
            first_field = false;
        }

        if let Some(hashes) = &contract_data.hashes {
            if !first_field {
                result.push(',');
            }
            result.push_str("\"hashes\":{");

            let mut first_hash = true;
            for (sig, hash) in hashes {
                if !first_hash {
                    result.push(',');
                }
                first_hash = false;

                result.push('"');
                result.push_str(sig);
                result.push_str("\":\"");
                result.push_str(hash);
                result.push('"');
            }

            result.push('}');
        }

        result.push('}');
    }

    result.push_str("},\"version\":\"");
    result.push_str(&data.version);
    result.push_str("\"}");

    result
}

