    let mut pretty_json = false;
    let mut _pretty_json_err = false;
    let mut _error_format = "human";
    let mut _error_format_human = "unicode";
    let mut _diagnostic_width: Option<usize> = None;
    let mut _no_warnings = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                print_version();
                return;
            }
            "-j" | "--threads" | "--jobs" => {
                i += 1;
                if i < args.len() {
                    _threads = args[i].parse().unwrap_or(8);
                }
            }
            "--evm-version" => {
                i += 1;
                if i < args.len() {
                    _evm_version = &args[i];
                }
            }
            "--stop-after" => {
                i += 1;
                if i < args.len() {
                    _stop_after = Some(args[i].clone());
                }
            }
            "--out-dir" => {
                i += 1;
                if i < args.len() {
                    out_dir = Some(args[i].clone());
                }
            }
            "--emit" => {
                i += 1;
                if i < args.len() {
                    emit = Some(args[i].clone());
                }
            }
            "-Z" => {
                i += 1;
                if i < args.len() {
                    let flag = args[i].clone();
                    if flag == "help" {
                        print_z_help();
                        return;
                    }
                    z_flags.push(flag);
                }
            }
            "--base-path" => {
                i += 1;
                if i < args.len() {
                    _base_path = Some(args[i].clone());
                }
            }
            "-I" | "--include-path" => {
                i += 1;
                if i < args.len() {
                    _include_paths.push(args[i].clone());
                }
            }
            "--allow-paths" => {
                i += 1;
                if i < args.len() {
                    _allow_paths = Some(args[i].clone());
                }
            }
            "--color" => {
                i += 1;
                if i < args.len() {
                    _color = &args[i];
                }
            }
            "-v" | "--verbose" => {
                _verbose = true;
            }
            "--pretty-json" => {
                pretty_json = true;
            }
            "--pretty-json-err" => {
                _pretty_json_err = true;
            }
            "--error-format" => {
                i += 1;
                if i < args.len() {
                    _error_format = &args[i];
                }
            }
            "--error-format-human" => {
                i += 1;
                if i < args.len() {
                    _error_format_human = &args[i];
                }
            }
            "--diagnostic-width" => {
                i += 1;
                if i < args.len() {
                    _diagnostic_width = args[i].parse().ok();
                }
            }
            "--no-warnings" => {
                _no_warnings = true;
            }
            _ if arg.starts_with("-") && arg.len() > 1 => {
                // Unknown flag or combined short flags - skip it
            }
            _ => {
                // This is input file or additional arguments
                input_files.push(arg.clone());
            }
        }
        i += 1;
    }

    // Handle input
    let mut input_sources: Vec<(String, String)> = Vec::new();

    let uses_stdin = input_files.iter().any(|f| f == "-");

    if uses_stdin {
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_ok() {
            input_sources.push(("<stdin>".to_string(), buffer));
        }
    } else if !input_files.is_empty() {
        for file in &input_files {
            match fs::read_to_string(file) {
                Ok(content) => {
                    input_sources.push((file.clone(), content));
                }
                Err(_) => {
                    eprintln!("error: file {} not found", file);
                    eprintln!();
                    eprintln!("error: aborting due to 1 previous error");
                    std::process::exit(1);
                }
            }
        }
    } else {
        eprintln!("error: no input files");
        eprintln!();
        eprintln!("error: aborting due to 1 previous error");
        std::process::exit(1);
    }

    // Parse and compile
    let mut output_contracts: BTreeMap<String, ContractData> = BTreeMap::new();

    for (filename, content) in input_sources {
        let parser = SolidityParser::new(content, filename.clone());
        let contracts = parser.extract_contracts();

        for contract in contracts {
            let key = format!("{}:{}", filename, contract.name);

            let mut abi = None;
            let mut hashes = None;

            let emit_abi = emit.as_ref().map(|e| e.contains("abi")).unwrap_or(false);
            let emit_hashes = emit.as_ref().map(|e| e.contains("hashes")).unwrap_or(false);

            if emit_abi {
                abi = Some(build_abi(&contract));
            }

            if emit_hashes {
                hashes = Some(build_hashes(&contract));
            }

            output_contracts.insert(key, ContractData { abi, hashes });
        }
    }

    let output = OutputData {
        contracts: output_contracts,
        version: VERSION.to_string(),
    };

    // Write output
    if let Some(dir) = out_dir {
        let path = PathBuf::from(dir).join("combined.json");
        let json = serialize_json(&output, false);
        let _ = fs::write(path, json);
    } else if emit.is_some() {
        let json = serialize_json(&output, pretty_json);
        println!("{}", json);
    }
}

