struct SolidityParser {
    content: String,
}

impl SolidityParser {
    fn new(content: String, _filename: String) -> Self {
        SolidityParser { content }
    }

    fn extract_contracts(&self) -> Vec<ContractInfo> {
        let mut contracts = Vec::new();
        let cleaned = self.remove_comments(&self.content);

        // Simple regex-like parsing for contracts
        let content = &cleaned;
        let bytes = content.as_bytes();
        let mut i = 0;

        while i < bytes.len() {
            // Look for contract/library/interface keyword
            if self.match_keyword(bytes, i, b"contract") {
                if let Some((name, body_start)) = self.extract_contract_name(content, i) {
                    if let Some(body) = self.extract_contract_body(content, body_start) {
                        let functions = self.extract_functions(&body);
                        contracts.push(ContractInfo {
                            name,
                            functions,
                        });
                    }
                }
                i += 8;
            } else if self.match_keyword(bytes, i, b"library") {
                if let Some((name, body_start)) = self.extract_contract_name(content, i) {
                    if let Some(body) = self.extract_contract_body(content, body_start) {
                        let functions = self.extract_functions(&body);
                        contracts.push(ContractInfo {
                            name,
                            functions,
                        });
                    }
                }
                i += 7;
            } else if self.match_keyword(bytes, i, b"interface") {
                if let Some((name, body_start)) = self.extract_contract_name(content, i) {
                    if let Some(body) = self.extract_contract_body(content, body_start) {
                        let functions = self.extract_functions(&body);
                        contracts.push(ContractInfo {
                            name,
                            functions,
                        });
                    }
                }
                i += 9;
            } else {
                i += 1;
            }
        }

        contracts
    }

    fn match_keyword(&self, bytes: &[u8], i: usize, keyword: &[u8]) -> bool {
        if i + keyword.len() > bytes.len() {
            return false;
        }

        if &bytes[i..i + keyword.len()] == keyword {
            if i + keyword.len() < bytes.len() {
                let next = bytes[i + keyword.len()];
                return !is_identifier_char(next);
            }
            return true;
        }

        false
    }

    fn extract_contract_name(&self, content: &str, start: usize) -> Option<(String, usize)> {
        let s = &content[start..];
        let keyword_len = if s.starts_with("contract") {
            8
        } else if s.starts_with("library") {
            7
        } else if s.starts_with("interface") {
            9
        } else {
            return None;
        };

        let after_keyword = &s[keyword_len..];
        let trimmed_start = after_keyword.len() - after_keyword.trim_start().len();
        let name_start = trimmed_start;

        let mut name_end = name_start;
        for c in after_keyword[name_start..].chars() {
            if !is_identifier_char(c as u8) {
                break;
            }
            name_end += c.len_utf8();
        }

        let name = after_keyword[name_start..name_end].to_string();

        let after_name = &after_keyword[name_end..];
        let mut body_start = name_end;
        for c in after_name.chars() {
            if c == '{' {
                return Some((name, start + keyword_len + body_start + 1));
            }
            body_start += c.len_utf8();
        }

        None
    }

    fn extract_contract_body(&self, content: &str, start: usize) -> Option<String> {
        let bytes = content.as_bytes();
        if start >= bytes.len() {
            return None;
        }

        let mut depth = 1;
        let mut end = start;

        for (i, &b) in bytes[start..].iter().enumerate() {
            if b == b'{' {
                depth += 1;
            } else if b == b'}' {
                depth -= 1;
                if depth == 0 {
                    end = start + i;
                    break;
                }
            }
        }

        Some(content[start..end].to_string())
    }

    fn extract_functions(&self, body: &str) -> Vec<FunctionInfo> {
        let mut functions = Vec::new();
        let bytes = body.as_bytes();
        let mut i = 0;

        // Extract functions
        while i < bytes.len() {
            if self.match_keyword(bytes, i, b"function") {
                if let Some(func_info) = self.parse_function(body, i) {
                    functions.push(func_info);
                }
                i += 8;
            } else if i + 11 <= bytes.len() && &bytes[i..i + 11] == b"constructor" {
                if let Some(func_info) = self.parse_function(body, i) {
                    functions.push(func_info);
                }
                i += 11;
            } else {
                i += 1;
            }
        }

        // Extract public state variables - must be done before sorting
        let state_vars = self.extract_state_variables(body);
        functions.extend(state_vars);

        functions
    }

    fn parse_function(&self, content: &str, start: usize) -> Option<FunctionInfo> {
        let s = &content[start..];

        // Find function name
        let paren_pos = s.find('(')?;
        let func_decl = &s[..paren_pos];

        let keywords = ["function", "constructor"];
        let mut name_start = 0;
        for kw in &keywords {
            if func_decl.contains(kw) {
                name_start = func_decl.find(kw)? + kw.len();
                break;
            }
        }

        let name_part = &func_decl[name_start..].trim_start();
        let name = name_part.split_whitespace().next().unwrap_or("").to_string();

        if name.is_empty() {
            return None;
        }

        // Find parameters
        let close_paren = s.find(')')?;
        let params_str = &s[paren_pos + 1..close_paren];
        let inputs = self.parse_parameters(params_str);

        // Find return types
        let after_paren = &s[close_paren + 1..];
        let returns_pos = after_paren.find("returns");
        let mut outputs = Vec::new();

        if let Some(ret_pos) = returns_pos {
            let ret_part = &after_paren[ret_pos + 7..];
            if let Some(ret_start) = ret_part.find('(') {
                if let Some(ret_end) = ret_part.find(')') {
                    let ret_str = &ret_part[ret_start + 1..ret_end];
                    outputs = self.parse_parameters(ret_str);
                }
            }
        }

        // Find state mutability
        let state_mutability = if s.contains("pure") {
            "pure"
        } else if s.contains("view") {
            "view"
        } else if s.contains("payable") {
            "payable"
        } else {
            "nonpayable"
        }
        .to_string();

        Some(FunctionInfo {
            name,
            inputs,
            outputs,
            state_mutability,
        })
    }

    fn parse_parameters(&self, params_str: &str) -> Vec<Parameter> {
        let mut params = Vec::new();

        if params_str.trim().is_empty() {
            return params;
        }

        for part in params_str.split(',') {
            let trimmed = part.trim();
            if trimmed.is_empty() {
                continue;
            }

            let tokens: Vec<&str> = trimmed.split_whitespace().collect();
            if tokens.is_empty() {
                continue;
            }

            let mut param_type = String::new();
            let mut param_name = String::new();

            if tokens.len() == 1 {
                param_type = self.normalize_type(tokens[0]);
            } else {
                for (i, token) in tokens.iter().enumerate() {
                    if i < tokens.len() - 1 {
                        if !param_type.is_empty() {
                            param_type.push(' ');
                        }
                        param_type.push_str(token);
                    } else {
                        param_name = token.to_string();
                    }
                }
                param_type = self.normalize_type(&param_type);
            }

            params.push(Parameter {
                name: param_name,
                param_type,
            });
        }

        params
    }

    fn normalize_type(&self, type_str: &str) -> String {
        let type_str = type_str.trim();
        match type_str {
            "uint" => "uint256".to_string(),
            "int" => "int256".to_string(),
            s => s.to_string(),
        }
    }

    fn extract_state_variables(&self, body: &str) -> Vec<FunctionInfo> {
        let mut vars = Vec::new();
        let lines: Vec<&str> = body.lines().collect();

        for line in lines {
            let trimmed = line.trim();

            // Skip if it's a function or event
            if trimmed.starts_with("function") || trimmed.starts_with("event") || trimmed.starts_with("constructor") {
                continue;
            }

            // Check if public state variable
            if trimmed.contains(" public ") {
                let parts: Vec<&str> = trimmed.split_whitespace().collect();
                if parts.len() >= 3 {
                    for (i, &part) in parts.iter().enumerate() {
                        if part == "public" && i > 0 && i < parts.len() - 1 {
                            let var_type = parts[i - 1];
                            let var_name = parts[i + 1].trim_end_matches(|c| c == ';' || c == '=' );

                            vars.push(FunctionInfo {
                                name: var_name.to_string(),
                                inputs: vec![],
                                outputs: vec![Parameter {
                                    name: String::new(),
                                    param_type: self.normalize_type(var_type),
                                }],
                                state_mutability: "view".to_string(),
                            });
                            break;
                        }
                    }
                }
            }
        }

        vars
    }

    fn remove_comments(&self, content: &str) -> String {
        let mut result = String::new();
        let chars: Vec<char> = content.chars().collect();
        let mut i = 0;

        while i < chars.len() {
            if i + 1 < chars.len() && chars[i] == '/' && chars[i + 1] == '/' {
                // Line comment
                i += 2;
                while i < chars.len() && chars[i] != '\n' {
                    i += 1;
                }
                if i < chars.len() {
                    result.push('\n');
                    i += 1;
                }
            } else if i + 1 < chars.len() && chars[i] == '/' && chars[i + 1] == '*' {
                // Block comment
                i += 2;
                while i + 1 < chars.len() {
                    if chars[i] == '*' && chars[i + 1] == '/' {
                        i += 2;
                        break;
                    }
                    if chars[i] == '\n' {
                        result.push('\n');
                    }
                    i += 1;
                }
            } else {
                result.push(chars[i]);
                i += 1;
            }
        }

        result
    }
}

fn is_identifier_char(c: u8) -> bool {
    (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9') || c == b'_'
}

#[derive(Debug, Clone)]
struct ContractInfo {
    name: String,
    functions: Vec<FunctionInfo>,
}

#[derive(Debug, Clone)]
struct FunctionInfo {
    name: String,
    inputs: Vec<Parameter>,
    outputs: Vec<Parameter>,
    state_mutability: String,
}

#[derive(Debug, Clone)]
struct Parameter {
    name: String,
    param_type: String,
}

#[derive(Debug, Clone)]
struct ContractData {
    abi: Option<Vec<AbiFunction>>,
    hashes: Option<BTreeMap<String, String>>,
}

#[derive(Debug, Clone)]
struct AbiFunction {
    type_: String,
    name: String,
    inputs: Vec<AbiInput>,
    outputs: Vec<AbiInput>,
    state_mutability: String,
}

#[derive(Debug, Clone)]
struct AbiInput {
    name: String,
    type_: String,
    internal_type: String,
}

#[derive(Debug, Clone)]
struct OutputData {
    contracts: BTreeMap<String, ContractData>,
    version: String,
}

fn build_abi(contract: &ContractInfo) -> Vec<AbiFunction> {
    let mut abi = Vec::new();

    for func in &contract.functions {
        let mut inputs = Vec::new();
        for (i, param) in func.inputs.iter().enumerate() {
            inputs.push(AbiInput {
                name: if param.name.is_empty() {
                    format!("arg{}", i)
                } else {
                    param.name.clone()
                },
                type_: param.param_type.clone(),
                internal_type: param.param_type.clone(),
            });
        }

        let mut outputs = Vec::new();
        for param in func.outputs.iter() {
            outputs.push(AbiInput {
                name: param.name.clone(),
                type_: param.param_type.clone(),
                internal_type: param.param_type.clone(),
            });
        }

        abi.push(AbiFunction {
            type_: "function".to_string(),
            name: func.name.clone(),
            inputs,
            outputs,
            state_mutability: func.state_mutability.clone(),
        });
    }

    abi
}

fn build_hashes(contract: &ContractInfo) -> BTreeMap<String, String> {
    let mut hashes = BTreeMap::new();

    for func in &contract.functions {
        let mut sig = func.name.clone();
        sig.push('(');
        sig.push_str(
            &func
                .inputs
                .iter()
                .map(|p| p.param_type.clone())
                .collect::<Vec<_>>()
                .join(","),
        );
        sig.push(')');

        let hash = compute_function_hash(&sig);
        hashes.insert(sig, hash);
    }

    hashes
}

fn compute_function_hash(signature: &str) -> String {
    let hash = keccak256(signature.as_bytes());
    format!("{:02x}{:02x}{:02x}{:02x}", hash[0], hash[1], hash[2], hash[3])
}

fn keccak256(input: &[u8]) -> [u8; 32] {
    keccak_sponge(input)
}

// Implement Keccak-256 sponge construction
fn keccak_sponge(input: &[u8]) -> [u8; 32] {
    // Keccak-256 parameters
    const RATE: usize = 136; // r = 1088 bits = 136 bytes for Keccak256
    const OUTPUT_LEN: usize = 32;

    let mut state = [0u64; 25];

    // Padding
    let mut padded = Vec::from(input);
    padded.push(0x06); // Domain separation for SHA-3
    while (padded.len() % RATE) != (RATE - 1) {
        padded.push(0x00);
    }
    padded.push(0x80); // End padding

    // Absorb phase
    for chunk in padded.chunks(RATE) {
        for (i, byte_chunk) in chunk.chunks(8).enumerate() {
            let mut val = 0u64;
            for (j, &b) in byte_chunk.iter().enumerate() {
                val |= (b as u64) << (8 * j);
            }
            state[i] ^= val;
        }
        keccak_f(&mut state);
    }

    // Squeeze phase
    let mut output = [0u8; 32];
    let mut out_pos = 0;
    while out_pos < OUTPUT_LEN {
        for i in 0..((RATE / 8).min((OUTPUT_LEN - out_pos) / 8)) {
            let bytes = state[i].to_le_bytes();
            let copy_len = (8).min(OUTPUT_LEN - out_pos);
            output[out_pos..out_pos + copy_len].copy_from_slice(&bytes[..copy_len]);
            out_pos += copy_len;
        }
        if out_pos < OUTPUT_LEN {
            keccak_f(&mut state);
        }
    }

    output
}

fn keccak_f(state: &mut [u64; 25]) {
    const ROUNDS: usize = 24;

    for round in 0..ROUNDS {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }

        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }

        for x in 0..5 {
            for y in 0..5 {
                state[x + 5 * y] ^= d[x];
            }
        }

        // Rho and Pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5 * y;
                b[y + 5 * ((2 * x + 3 * y) % 5)] = state[idx].rotate_left(RHO_OFFSETS[idx]);
            }
        }

        // Chi
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5 * y;
                state[idx] = b[idx] ^ ((!b[(x + 1) % 5 + 5 * y]) & b[(x + 2) % 5 + 5 * y]);
            }
        }

        // Iota
        state[0] ^= ROUND_CONSTANTS[round];
    }
}

const RHO_OFFSETS: [u32; 25] = [
    0, 1, 62, 28, 27,
    36, 44, 6, 55, 20,
    3, 10, 43, 25, 39,
    41, 45, 15, 21, 8,
    18, 2, 61, 56, 14,
];

const ROUND_CONSTANTS: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a,
    0x8000000080008000, 0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008a,
    0x0000000000000088, 0x0000000080000001, 0x000000008000008b,
    0x000000008000008a, 0x0000000000008089, 0x0000000000008003,
    0x0000000000008002, 0x0000000000000080, 0x000000000000800a,
    0x800000008000000a, 0x8000000080008081, 0x8000000000008080,
    0x0000000080000001, 0x8000000080008008, 0x0000000000000000,
];

fn serialize_json(data: &OutputData, pretty: bool) -> String {
    if pretty {
        format_json_pretty(data)
    } else {
        format_json_compact(data)
    }
}

fn format_json_compact(data: &OutputData) -> String {
    let mut result = String::from("{\"contracts\":{");

    let mut first_contract = true;
    for (key, contract_data) in &data.contracts {
        if !first_contract {
            result.push(',');
        }
        first_contract = false;

        result.push('"');
        result.push_str(key);
        result.push_str("\":{");

        let mut first_field = true;

        if let Some(abi) = &contract_data.abi {
            result.push_str("\"abi\":[");
            for (i, func) in abi.iter().enumerate() {
                if i > 0 {
                    result.push(',');
                }
                result.push_str("{\"type\":\"function\",\"name\":\"");
                result.push_str(&func.name);
                result.push_str("\",\"inputs\":[");

                for (j, input) in func.inputs.iter().enumerate() {
                    if j > 0 {
                        result.push(',');
                    }
                    result.push_str("{\"name\":\"");
                    result.push_str(&input.name);
                    result.push_str("\",\"type\":\"");
                    result.push_str(&input.type_);
                    result.push_str("\",\"internalType\":\"");
                    result.push_str(&input.internal_type);
                    result.push_str("\"}");
                }

                result.push_str("],\"outputs\":[");

                for (j, output) in func.outputs.iter().enumerate() {
                    if j > 0 {
                        result.push(',');
                    }
                    result.push_str("{\"name\":\"");
                    result.push_str(&output.name);
                    result.push_str("\",\"type\":\"");
                    result.push_str(&output.type_);
                    result.push_str("\",\"internalType\":\"");
                    result.push_str(&output.internal_type);
                    result.push_str("\"}");
                }

                result.push_str("],\"stateMutability\":\"");
                result.push_str(&func.state_mutability);
                result.push_str("\"}");
            }
            result.push(']');
            first_field = false;
        }

        if let Some(hashes) = &contract_data.hashes {
            if !first_field {
                result.push(',');
            }
            result.push_str("\"hashes\":{");

            let mut first_hash = true;
            for (sig, hash) in hashes {
                if !first_hash {
                    result.push(',');
                }
                first_hash = false;

                result.push('"');
                result.push_str(sig);
                result.push_str("\":\"");
                result.push_str(hash);
                result.push('"');
            }

            result.push('}');
        }

        result.push('}');
    }

    result.push_str("},\"version\":\"");
    result.push_str(&data.version);
    result.push_str("\"}");

    result
}

fn format_json_pretty(data: &OutputData) -> String {
    let mut result = String::from("{\n  \"contracts\": {\n");

    let mut first_contract = true;
    for (key, contract_data) in &data.contracts {
