                result.push_str(hash);
                result.push_str("\"");
            }

            result.push_str("\n      }\n");
        }

        result.push_str("    }");
    }

    result.push_str("\n  },\n");
    result.push_str("  \"version\": \"");
    result.push_str(&data.version);
    result.push_str("\"\n}\n");

    result
}

