struct SolidityParser {
    content: String,
}

impl SolidityParser {
    fn new(content: String, _filename: String) -> Self {
        SolidityParser { content }
    }

    fn extract_contracts(&self) -> Vec<ContractInfo> {
        let mut contracts = Vec::new();
        let cleaned = self.remove_comments(&self.content);

        // Simple regex-like parsing for contracts
        let content = &cleaned;
        let bytes = content.as_bytes();
        let mut i = 0;

        while i < bytes.len() {
            // Look for contract/library/interface keyword
            if self.match_keyword(bytes, i, b"contract") {
                if let Some((name, body_start)) = self.extract_contract_name(content, i) {
                    if let Some(body) = self.extract_contract_body(content, body_start) {
                        let functions = self.extract_functions(&body);
                        contracts.push(ContractInfo {
                            name,
                            functions,
                        });
                    }
                }
                i += 8;
            } else if self.match_keyword(bytes, i, b"library") {
                if let Some((name, body_start)) = self.extract_contract_name(content, i) {
                    if let Some(body) = self.extract_contract_body(content, body_start) {
                        let functions = self.extract_functions(&body);
                        contracts.push(ContractInfo {
                            name,
                            functions,
                        });
                    }
                }
                i += 7;
            } else if self.match_keyword(bytes, i, b"interface") {
                if let Some((name, body_start)) = self.extract_contract_name(content, i) {
                    if let Some(body) = self.extract_contract_body(content, body_start) {
                        let functions = self.extract_functions(&body);
                        contracts.push(ContractInfo {
                            name,
                            functions,
                        });
                    }
                }
                i += 9;
            } else {
                i += 1;
            }
        }

        contracts
    }

    fn match_keyword(&self, bytes: &[u8], i: usize, keyword: &[u8]) -> bool {
        if i + keyword.len() > bytes.len() {
            return false;
        }

        if &bytes[i..i + keyword.len()] == keyword {
            if i + keyword.len() < bytes.len() {
                let next = bytes[i + keyword.len()];
                return !is_identifier_char(next);
            }
            return true;
        }

        false
    }

    fn extract_contract_name(&self, content: &str, start: usize) -> Option<(String, usize)> {
        let s = &content[start..];
        let keyword_len = if s.starts_with("contract") {
            8
        } else if s.starts_with("library") {
            7
        } else if s.starts_with("interface") {
            9
        } else {
            return None;
        };

        let after_keyword = &s[keyword_len..];
        let trimmed_start = after_keyword.len() - after_keyword.trim_start().len();
        let name_start = trimmed_start;

        let mut name_end = name_start;
        for c in after_keyword[name_start..].chars() {
            if !is_identifier_char(c as u8) {
                break;
            }
            name_end += c.len_utf8();
        }

        let name = after_keyword[name_start..name_end].to_string();

        let after_name = &after_keyword[name_end..];
        let mut body_start = name_end;
        for c in after_name.chars() {
            if c == '{' {
                return Some((name, start + keyword_len + body_start + 1));
            }
            body_start += c.len_utf8();
        }

        None
    }

    fn extract_contract_body(&self, content: &str, start: usize) -> Option<String> {
        let bytes = content.as_bytes();
        if start >= bytes.len() {
            return None;
        }

        let mut depth = 1;
        let mut end = start;

        for (i, &b) in bytes[start..].iter().enumerate() {
            if b == b'{' {
                depth += 1;
            } else if b == b'}' {
                depth -= 1;
                if depth == 0 {
                    end = start + i;
                    break;
                }
            }
        }

        Some(content[start..end].to_string())
    }

    fn extract_functions(&self, body: &str) -> Vec<FunctionInfo> {
        let mut functions = Vec::new();
        let bytes = body.as_bytes();
        let mut i = 0;

        // Extract functions
        while i < bytes.len() {
            if self.match_keyword(bytes, i, b"function") {
                if let Some(func_info) = self.parse_function(body, i) {
                    functions.push(func_info);
                }
                i += 8;
            } else if i + 11 <= bytes.len() && &bytes[i..i + 11] == b"constructor" {
                if let Some(func_info) = self.parse_function(body, i) {
                    functions.push(func_info);
                }
                i += 11;
            } else {
                i += 1;
            }
        }

        // Extract public state variables - must be done before sorting
        let state_vars = self.extract_state_variables(body);
        functions.extend(state_vars);

        functions
    }

    fn parse_function(&self, content: &str, start: usize) -> Option<FunctionInfo> {
        let s = &content[start..];

        // Find function name
        let paren_pos = s.find('(')?;
        let func_decl = &s[..paren_pos];

        let keywords = ["function", "constructor"];
        let mut name_start = 0;
        for kw in &keywords {
            if func_decl.contains(kw) {
                name_start = func_decl.find(kw)? + kw.len();
                break;
            }
        }

        let name_part = &func_decl[name_start..].trim_start();
        let name = name_part.split_whitespace().next().unwrap_or("").to_string();

        if name.is_empty() {
            return None;
        }

        // Find parameters
        let close_paren = s.find(')')?;
        let params_str = &s[paren_pos + 1..close_paren];
        let inputs = self.parse_parameters(params_str);

        // Find return types and state mutability
        let after_paren = &s[close_paren + 1..];
        let mut outputs = Vec::new();
        let mut state_mutability = "nonpayable".to_string();

        // Find the opening brace that marks the end of the function signature
        let mut signature_end = 0;
        let mut found_brace = false;
        for c in after_paren.chars() {
            if c == '{' {
                found_brace = true;
                break;
            }
            signature_end += c.len_utf8();
        }

        if found_brace {
            let signature_part = &after_paren[..signature_end];

            // Check returns first
            if let Some(returns_pos) = signature_part.find("returns") {
                let ret_part = &signature_part[returns_pos + 7..];
                if let Some(ret_start) = ret_part.find('(') {
                    if let Some(ret_end) = ret_part.find(')') {
                        let ret_str = &ret_part[ret_start + 1..ret_end];
                        outputs = self.parse_parameters(ret_str);
                    }
                }
            }

            // Determine state mutability from the signature
            if signature_part.contains("pure") {
                state_mutability = "pure".to_string();
            } else if signature_part.contains("view") {
                state_mutability = "view".to_string();
            } else if signature_part.contains("payable") {
                state_mutability = "payable".to_string();
            }
        }

        Some(FunctionInfo {
            name,
            inputs,
            outputs,
            state_mutability,
        })
    }

    fn parse_parameters(&self, params_str: &str) -> Vec<Parameter> {
        let mut params = Vec::new();

        if params_str.trim().is_empty() {
            return params;
        }

        for part in params_str.split(',') {
            let trimmed = part.trim();
            if trimmed.is_empty() {
                continue;
            }

            let tokens: Vec<&str> = trimmed.split_whitespace().collect();
            if tokens.is_empty() {
                continue;
            }

            let mut param_type = String::new();
            let mut param_name = String::new();

            if tokens.len() == 1 {
                param_type = self.normalize_type(tokens[0]);
            } else {
                for (i, token) in tokens.iter().enumerate() {
                    if i < tokens.len() - 1 {
                        if !param_type.is_empty() {
                            param_type.push(' ');
                        }
                        param_type.push_str(token);
                    } else {
                        param_name = token.to_string();
                    }
                }
                param_type = self.normalize_type(&param_type);
            }

            params.push(Parameter {
                name: param_name,
                param_type,
            });
        }

        params
    }

    fn normalize_type(&self, type_str: &str) -> String {
        let type_str = type_str.trim();
        match type_str {
            "uint" => "uint256".to_string(),
            "int" => "int256".to_string(),
            s => s.to_string(),
        }
    }

    fn extract_state_variables(&self, body: &str) -> Vec<FunctionInfo> {
        let mut vars = Vec::new();
        let lines: Vec<&str> = body.lines().collect();

        for line in lines {
            let trimmed = line.trim();

            // Skip if it's a function or event
            if trimmed.starts_with("function") || trimmed.starts_with("event") || trimmed.starts_with("constructor") {
                continue;
            }

            // Check if public state variable
            if trimmed.contains(" public ") {
                let parts: Vec<&str> = trimmed.split_whitespace().collect();
                if parts.len() >= 3 {
                    for (i, &part) in parts.iter().enumerate() {
                        if part == "public" && i > 0 && i < parts.len() - 1 {
                            let var_type = parts[i - 1];
                            let var_name = parts[i + 1].trim_end_matches(|c| c == ';' || c == '=' );

                            vars.push(FunctionInfo {
                                name: var_name.to_string(),
                                inputs: vec![],
                                outputs: vec![Parameter {
                                    name: String::new(),
                                    param_type: self.normalize_type(var_type),
                                }],
                                state_mutability: "view".to_string(),
                            });
                            break;
                        }
                    }
                }
            }
        }

        vars
    }

    fn remove_comments(&self, content: &str) -> String {
        let mut result = String::new();
        let chars: Vec<char> = content.chars().collect();
        let mut i = 0;

        while i < chars.len() {
            if i + 1 < chars.len() && chars[i] == '/' && chars[i + 1] == '/' {
                // Line comment
                i += 2;
                while i < chars.len() && chars[i] != '\n' {
                    i += 1;
                }
                if i < chars.len() {
                    result.push('\n');
                    i += 1;
                }
            } else if i + 1 < chars.len() && chars[i] == '/' && chars[i + 1] == '*' {
                // Block comment
                i += 2;
                while i + 1 < chars.len() {
                    if chars[i] == '*' && chars[i + 1] == '/' {
                        i += 2;
                        break;
                    }
                    if chars[i] == '\n' {
                        result.push('\n');
                    }
                    i += 1;
                }
            } else {
                result.push(chars[i]);
                i += 1;
            }
        }

        result
    }
}

fn is_identifier_char(c: u8) -> bool {
    (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9') || c == b'_'
}

