            _ if arg.starts_with("-") && arg.len() > 1 => {
                // Unknown flag or combined short flags - skip it
            }
            _ => {
                // This is input file or additional arguments
                input_files.push(arg.clone());
            }
        }
        i += 1;
    }

    // Handle input
    let mut input_sources: Vec<(String, String)> = Vec::new();

    let uses_stdin = input_files.iter().any(|f| f == "-");

    if uses_stdin {
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_ok() {
            input_sources.push(("<stdin>".to_string(), buffer));
        }
    } else if !input_files.is_empty() {
        for file in &input_files {
            match fs::read_to_string(file) {
                Ok(content) => {
                    input_sources.push((file.clone(), content));
                }
                Err(_) => {
                    eprintln!("error: file {} not found", file);
                    eprintln!();
                    eprintln!("error: aborting due to 1 previous error");
                    std::process::exit(1);
                }
            }
        }
    } else {
        eprintln!("error: no input files");
        eprintln!();
        eprintln!("error: aborting due to 1 previous error");
        std::process::exit(1);
    }

    // Parse and compile
    let mut output_contracts: BTreeMap<String, ContractData> = BTreeMap::new();

    for (filename, content) in input_sources {
        let parser = SolidityParser::new(content, filename.clone());
        let contracts = parser.extract_contracts();

        for contract in contracts {
            let key = format!("{}:{}", filename, contract.name);

            let mut abi = None;
            let mut hashes = None;

            let emit_abi = emit.as_ref().map(|e| e.contains("abi")).unwrap_or(false);
            let emit_hashes = emit.as_ref().map(|e| e.contains("hashes")).unwrap_or(false);

            if emit_abi {
                abi = Some(build_abi(&contract));
            }

            if emit_hashes {
                hashes = Some(build_hashes(&contract));
            }

            output_contracts.insert(key, ContractData { abi, hashes });
        }
    }

    let output = OutputData {
        contracts: output_contracts,
        version: VERSION.to_string(),
    };

    // Write output
    if let Some(dir) = out_dir {
        let path = PathBuf::from(dir).join("combined.json");
        let json = serialize_json(&output, false);
        let _ = fs::write(path, json);
    } else if emit.is_some() {
        let json = serialize_json(&output, pretty_json);
        println!("{}", json);
    }
}

